from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    target = Path(path)
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected exactly one match, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


REPOSITORY = "backend/transfers/repository.py"
ENGINE = "backend/transfers/engine.py"
GATE = "backend/tests/post_audit_qualification.txt"
TEST = Path("backend/tests/test_second_pass_state002.py")

# STATE-002 durable executor-cleanup state lives with the universal execution
# attempt, not in an executor-specific table. DBARCH-001 will subsequently move
# schema mutation itself under the authoritative migration/bootstrap owner.
replace_once(
    REPOSITORY,
    '    "execution_attempts": {"candidate": "TEXT", "progress_at": "REAL"},\n',
    '    "execution_attempts": {\n'
    '        "candidate": "TEXT", "progress_at": "REAL",\n'
    '        "cleanup_state": "TEXT", "cleanup_attempts": "INTEGER NOT NULL DEFAULT 0",\n'
    '        "cleanup_retry_at": "REAL NOT NULL DEFAULT 0", "cleanup_error": "TEXT",\n'
    '    },\n',
)

state_anchor = '''    async def pause_intent(self, transfer_id: int, paused: bool) -> None:\n'''
state_methods = '''    async def cancel_with_execution_cleanup(self, transfer_id: int, *, expected_epoch: int, now: float) -> bool:\n        """Atomically close logical lifecycle and persist external cleanup responsibility."""\n        async with get_db() as db:\n            await db.execute("BEGIN IMMEDIATE")\n            row = await db.fetchone(\n                "SELECT status,progress,lifecycle_epoch,normalized_error FROM torrents WHERE id=?",\n                (transfer_id,),\n            )\n            if not row:\n                return False\n            current = TransferState(row["status"])\n            if current == TransferState.CANCELLED:\n                await db.commit()\n                return True\n            if not transition_allowed(current, TransferState.CANCELLED) or row["lifecycle_epoch"] != expected_epoch:\n                return False\n\n            await db.execute(\n                """UPDATE torrents SET status='cancelled',normalized_error=NULL,error_message=NULL,\n                    updated_at=CURRENT_TIMESTAMP WHERE id=?""",\n                (transfer_id,),\n            )\n            await db.execute(\n                "INSERT INTO events(torrent_id,level,message) VALUES(?,'info','Transfer cancelled')",\n                (transfer_id,),\n            )\n            await db.execute(\n                "INSERT INTO application_events(transfer_id,kind,detail) VALUES(?,'cancelled',NULL)",\n                (transfer_id,),\n            )\n            await db.execute(\n                """UPDATE execution_attempts SET cleanup_state='pending',cleanup_attempts=0,\n                    cleanup_retry_at=?,cleanup_error=NULL\n                    WHERE transfer_id=? AND authorized=1\n                    AND state IN ('prepared','queued','transferring','paused','unknown')\n                    AND id IN (SELECT execution_attempt_id FROM download_files\n                        WHERE torrent_id=? AND execution_attempt_id IS NOT NULL)""",\n                (now, transfer_id, transfer_id),\n            )\n            await db.execute(\n                """UPDATE download_files SET status='cancelled',normalized_error=NULL,updated_at=CURRENT_TIMESTAMP\n                    WHERE torrent_id=? AND status!='completed'""",\n                (transfer_id,),\n            )\n            await db.commit()\n        return True\n\n    async def pending_execution_cleanup(self, now: float, *, transfer_id: int | None = None):\n        async with get_db() as db:\n            where_transfer = " AND e.transfer_id=?" if transfer_id is not None else ""\n            params = (now, transfer_id) if transfer_id is not None else (now,)\n            rows = await db.fetchall(\n                """SELECT e.* FROM execution_attempts e JOIN torrents t ON t.id=e.transfer_id\n                    WHERE e.cleanup_state='pending' AND e.cleanup_retry_at<=?\n                    AND t.status IN ('cancelled','deleted')""" + where_transfer +\n                " ORDER BY e.transfer_id,e.created_at,e.id",\n                params,\n            )\n        return tuple((self._execution_attempt(row), int(row["cleanup_attempts"] or 0), codec.error(row["cleanup_error"])) for row in rows)\n\n    async def claim_execution_cleanup(self, attempt_id: str, *, now: float, lease_until: float) -> bool:\n        async with get_db() as db:\n            cursor = await db.execute(\n                """UPDATE execution_attempts SET cleanup_attempts=cleanup_attempts+1,\n                    cleanup_retry_at=?,updated_at=CURRENT_TIMESTAMP\n                    WHERE id=? AND cleanup_state='pending' AND cleanup_retry_at<=?""",\n                (lease_until, attempt_id, now),\n            )\n            await db.commit()\n        return cursor.rowcount == 1\n\n    async def execution_cleanup_retry(self, attempt_id: str, error: NormalizedError, retry_at: float | None) -> None:\n        async with get_db() as db:\n            await db.execute(\n                """UPDATE execution_attempts SET cleanup_state=?,cleanup_error=?,cleanup_retry_at=?,\n                    updated_at=CURRENT_TIMESTAMP WHERE id=? AND cleanup_state='pending'""",\n                ("pending" if retry_at is not None else "blocked", codec.dump(error), retry_at or 0, attempt_id),\n            )\n            await db.commit()\n\n    async def execution_cleanup_complete(self, attempt_id: str) -> None:\n        async with get_db() as db:\n            await db.execute(\n                """UPDATE execution_attempts SET cleanup_state='complete',cleanup_error=NULL,cleanup_retry_at=0,\n                    authorized=0,updated_at=CURRENT_TIMESTAMP WHERE id=?""",\n                (attempt_id,),\n            )\n            await db.commit()\n\n    async def execution_cleanup_status(self, attempt_id: str):\n        async with get_db() as db:\n            row = await db.fetchone(\n                "SELECT cleanup_state,cleanup_attempts,cleanup_retry_at,cleanup_error,authorized,state FROM execution_attempts WHERE id=?",\n                (attempt_id,),\n            )\n        if not row:\n            return None\n        return {\n            "state": row["cleanup_state"],\n            "attempts": int(row["cleanup_attempts"] or 0),\n            "retry_at": float(row["cleanup_retry_at"] or 0),\n            "error": codec.error(row["cleanup_error"]),\n            "authorized": bool(row["authorized"]),\n            "execution_state": row["state"],\n        }\n\n'''
replace_once(REPOSITORY, state_anchor, state_methods + state_anchor)

# Cleanup recovery is a separate reconciliation responsibility from active
# transfer reconciliation, so it runs even when the parent is already CANCELLED.
replace_once(
    ENGINE,
    '''    async def reconcile_executions(self):\n        """Observe each current attempt once, then dispatch in transfer priority order."""\n        async with self._execution_cycle_lock:\n            transfers = await self.repository.active()\n''',
    '''    async def reconcile_executions(self):\n        """Reconcile cleanup obligations, then active execution attempts."""\n        async with self._execution_cycle_lock:\n            await self._cleanup_executions_pending()\n            transfers = await self.repository.active()\n''',
)

old_cancel = '''    async def cancel(self, transfer_id: int):\n        lock = self._transfer_locks.setdefault(transfer_id, asyncio.Lock())\n        async with lock:\n            transfer = await self.repository.get(transfer_id)\n            if transfer is None:\n                raise KeyError(transfer_id)\n            if transfer.state == TransferState.CANCELLED:\n                return ()\n\n            # The durable lifecycle decision wins before executor I/O. The epoch\n            # closes the delete/retry race and state() supplies the canonical\n            # compare-and-transition boundary used by the rest of the engine.\n            if not await self.repository.state(\n                transfer_id, TransferState.CANCELLED, expected_epoch=transfer.epoch,\n            ):\n                current = await self.repository.get(transfer_id)\n                if current and current.state == TransferState.CANCELLED:\n                    return ()\n                raise TransferError(self._error(\n                    Category.RESOURCE_STATE_CONFLICT, Stage.EXECUTION, domain=Domain.LIFECYCLE,\n                    retryability=Retryability.NEVER, recovery=Recovery.REQUIRE_OPERATOR,\n                ))\n\n            challenge = await self.challenges.current(transfer_id)\n            if challenge:\n                await self.inputs.clear(challenge.id)\n                await self.challenges.clear_transfer(transfer_id)\n\n            cleanup_errors = []\n            for artifact in await self.repository.artifacts(transfer_id):\n                if artifact.execution:\n                    executor = self.registry.executors.get(artifact.execution.executor_id)\n                    if executor is None:\n                        error = self._error(\n                            Category.UNSUPPORTED_CAPABILITY, Stage.EXECUTION, domain=Domain.REQUEST,\n                            retryability=Retryability.NEVER,\n                        )\n                        outcome = TransferOutcome(OutcomeKind.FAILURE, error)\n                    else:\n                        try:\n                            outcome = await executor.cancel(artifact.execution)\n                            if not isinstance(outcome, TransferOutcome):\n                                raise TransferError(self._error(\n                                    Category.INVALID_ADAPTER_RESPONSE, Stage.EXECUTION, domain=Domain.EXECUTOR,\n                                    retryability=Retryability.NEVER,\n                                ))\n                        except Exception as exc:\n                            error = exc.error if isinstance(exc, TransferError) else unknown_failure(\n                                exc, integration_id=executor.descriptor.id, domain=Domain.EXECUTOR, stage=Stage.EXECUTION,\n                            )\n                            outcome = TransferOutcome(OutcomeKind.FAILURE, error)\n                    await self.repository.outcome(transfer_id, outcome, attempt_id=artifact.execution.attempt_id)\n                    if outcome.kind in {OutcomeKind.SUCCESS, OutcomeKind.CANCELLED}:\n                        attempt = next((item for item in await self.repository.executions(transfer_id)\n                                        if item.handle == artifact.execution), None)\n                        progress = attempt.progress if attempt else None\n                        await self.repository.execution(ExecutionObservation(\n                            artifact.execution, ExecutionState.CANCELLED, progress or TransferProgress(),\n                        ))\n                    elif outcome.error:\n                        cleanup_errors.append(outcome.error)\n                if artifact.state != "completed":\n                    await self.repository.artifact_state(artifact.id, "cancelled")\n            return tuple(cleanup_errors)\n\n'''
new_cancel = '''    async def cancel(self, transfer_id: int):\n        lock = self._transfer_locks.setdefault(transfer_id, asyncio.Lock())\n        async with lock:\n            transfer = await self.repository.get(transfer_id)\n            if transfer is None:\n                raise KeyError(transfer_id)\n\n            # STATE-002: logical cancellation and external termination are separate\n            # durable facts. Persist both the terminal parent and every outstanding\n            # execution cleanup obligation before contacting an executor.\n            if not await self.repository.cancel_with_execution_cleanup(\n                transfer_id, expected_epoch=transfer.epoch, now=self.clock(),\n            ):\n                current = await self.repository.get(transfer_id)\n                if not current or current.state != TransferState.CANCELLED:\n                    raise TransferError(self._error(\n                        Category.RESOURCE_STATE_CONFLICT, Stage.EXECUTION, domain=Domain.LIFECYCLE,\n                        retryability=Retryability.NEVER, recovery=Recovery.REQUIRE_OPERATOR,\n                    ))\n\n            challenge = await self.challenges.current(transfer_id)\n            if challenge:\n                await self.inputs.clear(challenge.id)\n                await self.challenges.clear_transfer(transfer_id)\n\n            return await self._cleanup_executions_pending(transfer_id=transfer_id)\n\n    def _executor_cleanup_exception(self, executor_id: str, exc: Exception) -> NormalizedError:\n        if isinstance(exc, TransferError):\n            return exc.error\n        native = unknown_failure(\n            exc, integration_id=executor_id, domain=Domain.EXECUTOR, stage=Stage.CLEANUP,\n        )\n        return NormalizedError(\n            Domain.CLEANUP, Category.REMOTE_CLEANUP_FAILED, Stage.CLEANUP,\n            retryability=Retryability.BACKOFF, recovery=Recovery.RETRY,\n            integration_id=executor_id, diagnostic=native.diagnostic,\n        )\n\n    async def _cleanup_executions_pending(self, *, transfer_id: int | None = None):\n        errors = []\n        now = self.clock()\n        for attempt, attempts, _previous_error in await self.repository.pending_execution_cleanup(\n            now, transfer_id=transfer_id,\n        ):\n            handle = attempt.handle\n            executor = self.registry.executors.get(handle.executor_id)\n            if executor is None:\n                error = self._error(\n                    Category.UNSUPPORTED_CAPABILITY, Stage.CLEANUP, domain=Domain.CLEANUP,\n                    retryability=Retryability.NEVER, recovery=Recovery.REQUIRE_OPERATOR,\n                )\n                await self.repository.execution_cleanup_retry(handle.attempt_id, error, None)\n                errors.append(error)\n                continue\n\n            lease_until = now + max(1.0, float(self.policy.retry_delay))\n            if not await self.repository.claim_execution_cleanup(\n                handle.attempt_id, now=now, lease_until=lease_until,\n            ):\n                continue\n            try:\n                observed = await executor.observe(handle)\n                if not isinstance(observed, ExecutionObservation) or observed.handle != handle:\n                    raise TransferError(self._error(\n                        Category.INVALID_ADAPTER_RESPONSE, Stage.CLEANUP, domain=Domain.EXECUTOR,\n                        retryability=Retryability.NEVER, recovery=Recovery.REQUIRE_OPERATOR,\n                    ))\n                await self.repository.execution(observed)\n                if observed.state in {\n                    ExecutionState.ABSENT, ExecutionState.CANCELLED,\n                    ExecutionState.SUCCEEDED, ExecutionState.FAILED,\n                }:\n                    await self.repository.execution_cleanup_complete(handle.attempt_id)\n                    continue\n\n                outcome = await executor.cancel(handle)\n                if not isinstance(outcome, TransferOutcome):\n                    raise TransferError(self._error(\n                        Category.INVALID_ADAPTER_RESPONSE, Stage.CLEANUP, domain=Domain.EXECUTOR,\n                        retryability=Retryability.NEVER, recovery=Recovery.REQUIRE_OPERATOR,\n                    ))\n                await self.repository.outcome(attempt.transfer_id, outcome, attempt_id=handle.attempt_id)\n                if outcome.kind not in {OutcomeKind.SUCCESS, OutcomeKind.CANCELLED, OutcomeKind.SKIPPED}:\n                    error = outcome.error or self._error(\n                        Category.REMOTE_CLEANUP_FAILED, Stage.CLEANUP, domain=Domain.CLEANUP,\n                        retryability=Retryability.BACKOFF, recovery=Recovery.RETRY,\n                    )\n                    raise TransferError(error)\n\n                confirmed = await executor.observe(handle)\n                if not isinstance(confirmed, ExecutionObservation) or confirmed.handle != handle:\n                    raise TransferError(self._error(\n                        Category.INVALID_ADAPTER_RESPONSE, Stage.CLEANUP, domain=Domain.EXECUTOR,\n                        retryability=Retryability.NEVER, recovery=Recovery.REQUIRE_OPERATOR,\n                    ))\n                await self.repository.execution(confirmed)\n                if confirmed.state not in {\n                    ExecutionState.ABSENT, ExecutionState.CANCELLED,\n                    ExecutionState.SUCCEEDED, ExecutionState.FAILED,\n                }:\n                    raise TransferError(self._error(\n                        Category.REMOTE_CLEANUP_FAILED, Stage.CLEANUP, domain=Domain.CLEANUP,\n                        retryability=Retryability.BACKOFF, recovery=Recovery.RETRY,\n                    ))\n                await self.repository.execution_cleanup_complete(handle.attempt_id)\n            except Exception as exc:\n                error = self._executor_cleanup_exception(handle.executor_id, exc)\n                decision = self.policy.retry(error, attempts + 1, now)\n                await self.repository.execution_cleanup_retry(handle.attempt_id, error, decision.retry_at)\n                errors.append(error)\n        return tuple(errors)\n\n'''
replace_once(ENGINE, old_cancel, new_cancel)

TEST.write_text('''"""Second-pass STATE-002 durable external-execution cleanup contracts."""\nimport asyncio\nfrom types import SimpleNamespace\n\nimport pytest\nimport pytest_asyncio\n\nimport db.database as database\nfrom fake_integrations import MemoryExecutor, ParcelProvider\nfrom transfers.engine import TransferEngine\nfrom transfers.errors import Category, Domain, NormalizedError, Recovery, Retryability, Stage\nfrom transfers.models import ExecutionState, OutcomeKind, TransferOutcome, TransferProgress, TransferRequest, TransferState\nfrom transfers.policy import TransferPolicy\nfrom transfers.registry import IntegrationRegistry\nfrom transfers.repository import TransferRepository\n\n\nclass Clock:\n    def __init__(self, value=1000.0):\n        self.value = value\n\n    def __call__(self):\n        return self.value\n\n\n@pytest_asyncio.fixture\nasync def core(tmp_path, monkeypatch):\n    monkeypatch.setattr(database, "DB_PATH", tmp_path / "state002.db")\n    await database.init_db()\n    repository = TransferRepository()\n    registry = IntegrationRegistry()\n    provider = ParcelProvider()\n    executor = MemoryExecutor(repository.authorize_execution)\n    registry.register_provider(provider)\n    registry.register_executor(executor)\n    clock = Clock()\n    engine = TransferEngine(\n        repository, registry, download_root=str(tmp_path / "payloads"),\n        policy=TransferPolicy(max_attempts=3, retry_delay=0, resolution_retry_delay=0, adoption_stability_seconds=0),\n        clock=clock,\n    )\n    await engine.initialize()\n    return SimpleNamespace(engine=engine, repository=repository, registry=registry, provider=provider, executor=executor, clock=clock)\n\n\nasync def executing(core):\n    transfer = await core.engine.submit((TransferRequest("parcel", "box", name="payload.bin"),), deduplicate=False)\n    await core.engine.tick()\n    artifact = (await core.repository.artifacts(transfer.id))[0]\n    assert artifact.execution is not None\n    return transfer, artifact\n\n\ndef transient_cleanup_error():\n    return NormalizedError(\n        Domain.CLEANUP, Category.REMOTE_CLEANUP_FAILED, Stage.CLEANUP,\n        retryability=Retryability.BACKOFF, recovery=Recovery.RETRY,\n    )\n\n\n@pytest.mark.asyncio\nasync def test_state002_immediate_executor_cancel_satisfies_cleanup_without_resurrection(core):\n    transfer, artifact = await executing(core)\n    assert await core.engine.cancel(transfer.id) == ()\n    status = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n    assert (await core.repository.get(transfer.id)).state == TransferState.CANCELLED\n    assert status["state"] == "complete"\n    assert status["authorized"] is False\n    assert status["attempts"] == 1\n    before = len([call for call in core.executor.calls if call[0] == "cancel"])\n    assert await core.engine.cancel(transfer.id) == ()\n    assert len([call for call in core.executor.calls if call[0] == "cancel"]) == before\n\n\n@pytest.mark.asyncio\nasync def test_state002_failed_cancel_is_durable_while_parent_is_already_cancelled(core):\n    transfer, artifact = await executing(core)\n    error = transient_cleanup_error()\n\n    async def fail_cancel(_handle):\n        return TransferOutcome(OutcomeKind.FAILURE, error)\n\n    core.executor.cancel = fail_cancel\n    assert await core.engine.cancel(transfer.id) == (error,)\n    status = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n    assert (await core.repository.get(transfer.id)).state == TransferState.CANCELLED\n    assert (await core.repository.artifacts(transfer.id))[0].state == "cancelled"\n    assert status["state"] == "pending"\n    assert status["attempts"] == 1\n    assert status["error"] == error\n    assert status["authorized"] is True\n\n\n@pytest.mark.asyncio\nasync def test_state002_failed_cancel_survives_restart_and_converges(core):\n    transfer, artifact = await executing(core)\n    error = transient_cleanup_error()\n    original_cancel = core.executor.cancel\n    calls = 0\n\n    async def fail_once(handle):\n        nonlocal calls\n        calls += 1\n        if calls == 1:\n            return TransferOutcome(OutcomeKind.FAILURE, error)\n        return await original_cancel(handle)\n\n    core.executor.cancel = fail_once\n    assert await core.engine.cancel(transfer.id) == (error,)\n    restarted = TransferEngine(\n        TransferRepository(), core.registry, download_root=core.engine.root, policy=core.engine.policy, clock=core.clock,\n    )\n    await restarted.initialize()\n    await restarted.reconcile_executions()\n    status = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n    assert calls == 2\n    assert status["state"] == "complete"\n    assert status["authorized"] is False\n    assert (await core.repository.get(transfer.id)).state == TransferState.CANCELLED\n\n\n@pytest.mark.asyncio\nasync def test_state002_repeated_failures_are_bounded_and_obligation_remains_truthful(core):\n    transfer, artifact = await executing(core)\n    error = transient_cleanup_error()\n\n    async def fail_cancel(_handle):\n        return TransferOutcome(OutcomeKind.FAILURE, error)\n\n    core.executor.cancel = fail_cancel\n    for _ in range(4):\n        await core.engine.cancel(transfer.id)\n    status = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n    assert status["attempts"] == 3\n    assert status["state"] == "blocked"\n    assert status["error"] == error\n    assert status["authorized"] is True\n    assert (await core.repository.get(transfer.id)).state == TransferState.CANCELLED\n\n\n@pytest.mark.asyncio\nasync def test_state002_late_executor_success_only_reconciles_external_cleanup(core):\n    transfer, artifact = await executing(core)\n    error = transient_cleanup_error()\n\n    async def fail_cancel(_handle):\n        return TransferOutcome(OutcomeKind.FAILURE, error)\n\n    core.executor.cancel = fail_cancel\n    await core.engine.cancel(transfer.id)\n    core.executor.finish(artifact.execution, materialize=False)\n    restarted = TransferEngine(\n        TransferRepository(), core.registry, download_root=core.engine.root, policy=core.engine.policy, clock=core.clock,\n    )\n    await restarted.initialize()\n    await restarted.reconcile_executions()\n    status = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n    assert status["state"] == "complete"\n    assert status["execution_state"] == ExecutionState.SUCCEEDED\n    assert (await core.repository.get(transfer.id)).state == TransferState.CANCELLED\n    assert (await core.repository.artifacts(transfer.id))[0].state == "cancelled"\n\n\n@pytest.mark.asyncio\nasync def test_state002_repeated_user_cancel_does_not_duplicate_cleanup_obligation(core):\n    transfer, artifact = await executing(core)\n    error = transient_cleanup_error()\n    entered = asyncio.Event()\n    release = asyncio.Event()\n\n    async def blocked_failure(_handle):\n        entered.set()\n        await release.wait()\n        return TransferOutcome(OutcomeKind.FAILURE, error)\n\n    core.executor.cancel = blocked_failure\n    first = asyncio.create_task(core.engine.cancel(transfer.id))\n    await entered.wait()\n    assert (await core.repository.get(transfer.id)).state == TransferState.CANCELLED\n    release.set()\n    assert await first == (error,)\n    await core.engine.cancel(transfer.id)\n    statuses = [item for item in await core.repository.executions(transfer.id) if item.handle.attempt_id == artifact.execution.attempt_id]\n    assert len(statuses) == 1\n    cleanup = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n    assert cleanup["attempts"] == 2\n\n\n@pytest.mark.asyncio\nasync def test_state002_cancel_commit_contains_cleanup_obligation_before_executor_io(core):\n    transfer, artifact = await executing(core)\n    observed = {}\n\n    async def inspect_then_fail(_handle):\n        observed["parent"] = (await core.repository.get(transfer.id)).state\n        observed["artifact"] = (await core.repository.artifacts(transfer.id))[0].state\n        observed["cleanup"] = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n        raise asyncio.TimeoutError("cancel timeout containing https://user:password@example.test/secret")\n\n    core.executor.cancel = inspect_then_fail\n    errors = await core.engine.cancel(transfer.id)\n    assert observed["parent"] == TransferState.CANCELLED\n    assert observed["artifact"] == "cancelled"\n    assert observed["cleanup"]["state"] == "pending"\n    assert observed["cleanup"]["attempts"] == 1\n    assert errors and errors[0].category == Category.REMOTE_CLEANUP_FAILED\n    status = await core.repository.execution_cleanup_status(artifact.execution.attempt_id)\n    assert "password" not in status["error"].diagnostic\n    assert "example.test" not in status["error"].diagnostic\n''', encoding="utf-8")

replace_once(
    GATE,
    '# STATE-001\ntests/test_audit_remediation_state.py\n',
    '# STATE-001 + STATE-002\ntests/test_audit_remediation_state.py\ntests/test_second_pass_state002.py\n',
)
